// Import of required libraries
import { test, expect, SkyrampClient, getBaseUrl, getValue, getResponseValue } from '@skyramp/skyramp';
import { createCollection, createLink, addLinkToCollection, getLinks, deleteCollection } from './skyrampUtils';

// URL for test requests
const URL_localhost = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:3000");

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();
    // Declaration of variables
    const sort = "0";

    const collectionsPostResponse = await createCollection(client, "tb-src-collection");
    expect(collectionsPostResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(collectionsPostResponse, "response.name"), 'name').toBe("tb-src-collection");
    expect(getResponseValue(collectionsPostResponse, "response.description"), 'description').toBe("");
    expect(getResponseValue(collectionsPostResponse, "response.color"), 'color').toBe("#0ea5e9");
    expect(getResponseValue(collectionsPostResponse, "response.id"), 'id').toBeGreaterThan(0);
    expect(getResponseValue(collectionsPostResponse, "response.createdAt"), 'createdAt').toMatch(/^\d{4}-\d{2}-\d{2}T/);

    const collectionsPost1Response = await createCollection(client, "tb-dst-collection");
    expect(collectionsPost1Response.statusCode, 'status code').toBe(200);
    expect(getResponseValue(collectionsPost1Response, "response.name"), 'name').toBe("tb-dst-collection");
    expect(getResponseValue(collectionsPost1Response, "response.id"), 'id').toBeGreaterThan(0);

    const v1LinksPostResponse = await createLink(
        client,
        getResponseValue(collectionsPostResponse, "response.id"),
        "tb-move-link",
        "https://example.com/tb-move"
    );
    expect(v1LinksPostResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(v1LinksPostResponse, "response.name"), 'name').toBe("tb-move-link");
    expect(getResponseValue(v1LinksPostResponse, "response.url"), 'url').toBe("https://example.com/tb-move");
    expect(getResponseValue(v1LinksPostResponse, "response.type"), 'type').toBe("url");
    expect(getResponseValue(v1LinksPostResponse, "response.id"), 'id').toBeGreaterThan(0);
    expect(getResponseValue(v1LinksPostResponse, "response.collectionId"), 'link starts in the source collection')
        .toBe(getResponseValue(collectionsPostResponse, "response.id"));

    const linksPostResponse = await addLinkToCollection(
        client,
        getResponseValue(collectionsPost1Response, "response.id"),
        getResponseValue(v1LinksPostResponse, "response.id")
    );
    expect(linksPostResponse.statusCode, 'status code').toBe(201);
    expect(getResponseValue(linksPostResponse, "response.collectionId"), 'collectionId')
        .toBe(getResponseValue(collectionsPost1Response, "response.id"));
    expect(getResponseValue(linksPostResponse, "response.linkId"), 'linkId')
        .toBe(getResponseValue(v1LinksPostResponse, "response.id"));

    const v1LinksGetResponse = await getLinks(
        client,
        getResponseValue(linksPostResponse, "response.collectionId"),
        sort
    );
    expect(v1LinksGetResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(v1LinksGetResponse, "response").length, 'destination holds exactly the moved link').toBe(1);
    expect(getResponseValue(v1LinksGetResponse, "response.0.id"), 'id')
        .toBe(getResponseValue(v1LinksPostResponse, "response.id"));
    expect(getResponseValue(v1LinksGetResponse, "response.0.name"), 'name').toBe("tb-move-link");
    expect(getResponseValue(v1LinksGetResponse, "response.0.collectionId"), 'collectionId')
        .toBe(getResponseValue(collectionsPost1Response, "response.id"));
    expect(getResponseValue(v1LinksGetResponse, "response.1"), 'no second link').toBeNull();

    const v1LinksGet1Response = await getLinks(
        client,
        getResponseValue(v1LinksPostResponse, "response.collectionId"),
        sort
    );
    expect(v1LinksGet1Response.statusCode, 'status code').toBe(200);
    expect(getResponseValue(v1LinksGet1Response, "response").length, 'source no longer holds the link').toBe(0);
    expect(getResponseValue(v1LinksGet1Response, "response.0"), 'source listing is empty').toBeNull();

    // Request Body
    const v1LinksDeleteRequestBody: string = `{
        "linkIds": [
            918273643
        ]
    }`;

    // Definition of authentication header
    const headers: Record<string, string> = {};
    if (process.env.SKYRAMP_TEST_TOKEN && process.env.SKYRAMP_TEST_TOKEN != "") {
        headers["Authorization"] = "Bearer " + process.env.SKYRAMP_TEST_TOKEN;
    }

    // Execute Request
    const v1LinksDeleteResponse = await client.sendRequest({
        url: URL_localhost,
        path: "/api/v1/links",
        method: "DELETE",
        headers: headers,
        body: v1LinksDeleteRequestBody,
        dataOverride: {"linkIds.0": getResponseValue(v1LinksPostResponse, "response.id")}
    });

    // Generated Assertions
    expect(v1LinksDeleteResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(v1LinksDeleteResponse, "response.count"), 'exactly the link this test created was deleted').toBe(1);

    const collectionsCollectionsDeleteResponse = await deleteCollection(
        client,
        getResponseValue(collectionsPostResponse, "response.id")
    );
    expect(collectionsCollectionsDeleteResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(collectionsCollectionsDeleteResponse, "response.id"), 'id')
        .toBe(getResponseValue(collectionsPostResponse, "response.id"));

    const collectionsCollectionsDelete1Response = await deleteCollection(
        client,
        getResponseValue(collectionsPost1Response, "response.id")
    );
    expect(collectionsCollectionsDelete1Response.statusCode, 'status code').toBe(200);
    expect(getResponseValue(collectionsCollectionsDelete1Response, "response.id"), 'id')
        .toBe(getResponseValue(collectionsPost1Response, "response.id"));
});
